use argon2::{
    password_hash::{rand_core::OsRng as ArgonRng, PasswordHasher, SaltString},
    Argon2,
};
use std::fs::{self, File};
use std::io::{Read, Write};
use std::path::Path;

const NONCE_SIZE: usize = 12;

pub struct EncryptionResult {
    pub encrypted_data: Vec<u8>,
    pub nonce: [u8; NONCE_SIZE],
}

pub fn derive_key_from_password(password: &str, salt: &SaltString) -> Result<Key<Aes256Gcm>, String> {
    let argon2 = Argon2::default();
    let password_hash = argon2
        .hash_password(password.as_bytes(), salt)
        .map_err(|e| format!("Key derivation failed: {}", e))?;

    let hash_bytes = password_hash.hash.unwrap().as_bytes();
    if hash_bytes.len() < 32 {
        return Err("Derived key too short".to_string());
    }

    let key_slice = &hash_bytes[..32];
    Ok(*Key::<Aes256Gcm>::from_slice(key_slice))
}

pub fn encrypt_file(
    input_path: &Path,
    output_path: &Path,
    password: &str,
) -> Result<EncryptionResult, String> {
    let mut file = File::open(input_path)
        .map_err(|e| format!("Failed to open input file: {}", e))?;
    
    let mut plaintext = Vec::new();
    file.read_to_end(&mut plaintext)
        .map_err(|e| format!("Failed to read input file: {}", e))?;

    let salt = SaltString::generate(&mut ArgonRng);
    let key = derive_key_from_password(password, &salt)?;

    let cipher = Aes256Gcm::new(&key);
    let mut nonce_bytes = [0u8; NONCE_SIZE];
    OsRng.fill(&mut nonce_bytes);
    let nonce = Nonce::from_slice(&nonce_bytes);

    let encrypted_data = cipher
        .encrypt(nonce, plaintext.as_ref())
        .map_err(|e| format!("Encryption failed: {}", e))?;

    let mut output_file = File::create(output_path)
        .map_err(|e| format!("Failed to create output file: {}", e))?;

    output_file.write_all(&salt.as_bytes())
        .map_err(|e| format!("Failed to write salt: {}", e))?;
    output_file.write_all(&encrypted_data)
        .map_err(|e| format!("Failed to write encrypted data: {}", e))?;

    Ok(EncryptionResult {
        encrypted_data,
        nonce: nonce_bytes,
    })
}

pub fn decrypt_file(
    input_path: &Path,
    output_path: &Path,
    password: &str,
    nonce: &[u8; NONCE_SIZE],
) -> Result<Vec<u8>, String> {
    let mut file = File::open(input_path)
        .map_err(|e| format!("Failed to open encrypted file: {}", e))?;

    let mut file_content = Vec::new();
    file.read_to_end(&mut file_content)
        .map_err(|e| format!("Failed to read encrypted file: {}", e))?;

    if file_content.len() < 22 {
        return Err("File too short to contain salt and data".to_string());
    }

    let salt_str = std::str::from_utf8(&file_content[..22])
        .map_err(|e| format!("Invalid salt encoding: {}", e))?;
    let salt = SaltString::new(salt_str)
        .map_err(|e| format!("Invalid salt format: {}", e))?;
    
    let encrypted_data = &file_content[22..];
    let key = derive_key_from_password(password, &salt)?;

    let cipher = Aes256Gcm::new(&key);
    let nonce = Nonce::from_slice(nonce);

    let decrypted_data = cipher
        .decrypt(nonce, encrypted_data)
        .map_err(|e| format!("Decryption failed: {}", e))?;

    let mut output_file = File::create(output_path)
        .map_err(|e| format!("Failed to create output file: {}", e))?;
    
    output_file.write_all(&decrypted_data)
        .map_err(|e| format!("Failed to write decrypted data: {}", e))?;

    Ok(decrypted_data)
}

